function GachaponComponent:InitialGachapon(jsonStr)
    local datas = nil
    if type(jsonStr) == 'string' then
        datas = table.deserialize(jsonStr)
    else
        datas = checkTable(jsonStr)
    end
    --print(table.dump(datas))
    self.AllGachapon = {}
    self.rookieCall = {}
    for k,v in pairs(datas) do
        if k == "pools" then
            for i = 1, #v do
                ---@type GachaponDojo
                local dojo = GachaponDojo.New()
                dojo:Fill(v[i])

                if not (self.Filter ~= nil or self.FilterPoolType ~= nil) then
                    table.insert(self.AllGachapon, dojo)

                else
                    if self.FilterPoolType == checkNumber(dojo.poolType) then
                        table.insert(self.AllGachapon, dojo)
                        break

                    elseif (self.Filter ~= nil and table.indexof(self.Filter, dojo.poolId) ~= false) then
                        table.insert(self.AllGachapon, dojo)

                    end
                end
            end
            print(table.toString(self.AllGachapon, 'AllGachaponPools'))
        elseif k == "rookieCall" then
            for kk, vv in pairs(v) do
                local a = checkNumber(kk)
                if a == 1 or a == 2 then
                    if self.rookieCall[a] == nil then
                        self.rookieCall[a] = {}
                    end
                    for kkk, vvv in pairs(vv) do
                        ---@type RewardDojo
                        local dojo = RewardDojo.New()
                        dojo:Fill(vvv)
                        table.insert(self.rookieCall[a], dojo)
                    end
                    
                else
                    self.rookieCall[a] = checkNumber(vv)
                end
            end
        else
            self[k] = v
        end
    end

    --printInfo(table.dump(self.rookieCall[GachaponConstants.NewComerKey.CurrentResult]))
    
    table.sort(self.AllGachapon, function(a, b)
        local aIsFinish = self:IsFinishPools(a) and 1 or 0
        local bIsFinish = self:IsFinishPools(b) and 1 or 0
        if aIsFinish == bIsFinish then
            if a.sort == b.sort then
                return a.poolId < b.poolId
            else
                return a.sort < b.sort
            end
        else
            return aIsFinish < bIsFinish
        end
    end)
    self:UpdateConsumeDatas(self.AllGachapon)
    self:UpdateHomeActivityDatasByCallHome()
end

---@return boolean 卡池抽卡是否结束
function GachaponComponent:IsFinishPools(pool)
    if GachaponUtils.IsOverseaStepType(pool.poolType) then
        if pool.activity.stepNum > pool.activity.totalStepNum then
            return true
        end
    end
    return false
end

---@return boolean
function GachaponComponent:IsRookieCallStarted()
    return self.rookieCallOver == GachaponConstants.RookieCallState.Started and isSet(self.rookieCall, GachaponConstants.NewComerKey.CurrentResult)
end

---@return boolean
function GachaponComponent:IsRookieCallEnded()
    return self.rookieCallOver == GachaponConstants.RookieCallState.Ended
end

