---@param idx integer
---@return GachaponDojo
function GachaponComponent:GetPoolByIndex(idx)
    if self.AllGachapon == nil then
        return nil
    end
    if #self.AllGachapon < idx then
        return nil
    end
    return self.AllGachapon[idx]
end

---@param poolId integer
---@return GachaponDojo
function GachaponComponent:GetPoolById(poolId)
    local find = false
    for k,v in ipairs(self.AllGachapon) do
        if v.poolId == poolId then
            find = v
            break
        end
    end
    return find
end

