---@param id integer
---@param callType GachaponConstants.CallType @ 抽卡类型：1 单抽 type 2 十连
---@param result RewardDojo[] | integer
function GachaponComponent:CallsPoolById(id, callType, result)
    local pool = self:GetPoolById(id)
    if type(pool) == "boolean" then
        return 
    end
    if not GachaponUtils.IsNewComerType(pool.poolType) then
        pool.callTimes = pool.callTimes + (callType == GachaponConstants.CallType.Ten and 10 or 1)
        if checkInt(pool.maxTimes) ~= -1 and pool.callTimes >= checkInt(pool.maxTimes) then
            table.removebyvalue(self.AllGachapon, pool)
        end
    else
        self.rookieCallOver = GachaponConstants.RookieCallState.Started
        self.rookieCall[GachaponConstants.NewComerKey.Consume] = 1
        local cnt = checkNumber(self.rookieCall[GachaponConstants.NewComerKey.CurrentCount])
        cnt = cnt + 1
        self.rookieCall[GachaponConstants.NewComerKey.CurrentCount] = cnt
        self.rookieCall[GachaponConstants.NewComerKey.CurrentResult] = result
    end
    
end

function GachaponComponent:SaveRookieCall()
    self.rookieCall[GachaponConstants.NewComerKey.CacheResult] = self.rookieCall[GachaponConstants.NewComerKey.CurrentResult]
end

---@param pool GachaponDojo
function GachaponComponent:DrawRookieCall(pool)
    self.rookieCallOver = GachaponConstants.RookieCallState.Ended
    pool.callTimes = pool.callTimes + 999
    table.removebyvalue(self.AllGachapon, pool)
end

---@param pool GachaponDojo
---@return boolean
function GachaponComponent:WillConsume(pool)
    if not GachaponUtils.IsNewComerType(pool.poolType) then
        return true
    end

    if self.rookieCall == nil then
        return true
    end

    if not isSet(self.rookieCall, GachaponConstants.NewComerKey.Consume) then
        return true
    end
    
    return false
end


---@param dataList table[]
function GachaponComponent:UpdateHomeActivityDatas(dataList)
    GameUtils.ConventSecondToTimeStamp(dataList)
    self:UpdateHomeActivityDatasByData(dataList)
end


function GachaponComponent:UpdateHomeActivityDatasByCallHome()
    local homeActivityDataList = {}
    for _, gachaponDojo in ipairs(self.AllGachapon) do
        local callHomeData = nil
        if gachaponDojo.poolType == GachaponConstants.PoolType.OverseaAccount then
            callHomeData = {
                poolId   = gachaponDojo.poolId,
                poolType = gachaponDojo.poolType,
                entrance = gachaponDojo.entrance,
            }
        else
            local activityData = checkTable(gachaponDojo.activity)
            if next(activityData) ~= nil then
                callHomeData = {
                    poolId    = gachaponDojo.poolId,
                    poolType  = gachaponDojo.poolType,
                    entrance  = gachaponDojo.entrance,
                    id        = activityData.activityUuid,
                    startTime = activityData.startTime,
                    endTime   = activityData.endTime,
                    closeTime = activityData.closeTime,
                }
            end
        end
        if callHomeData then
            table.insert(homeActivityDataList, callHomeData)
        end
    end
    if #homeActivityDataList > 0 then
        self:UpdateHomeActivityDatasByData(homeActivityDataList)
    end
end

---@param dataList table[]
function GachaponComponent:UpdateHomeActivityDatasByData(dataList)
    self.homeActivityDatas = {}

    for _, activityData in ipairs(dataList or {}) do
        local poolId   = checkInt(activityData.poolId)
        local poolType = checkInt(activityData.poolType)
        local entrance = checkString(activityData.entrance)
        if not string.isEmpty(entrance) then
            table.insert(self.homeActivityDatas, {
                poolId     = poolId,
                entrance   = entrance,
                poolType   = poolType,
                activityId = checkInt(activityData.id),
                startTime  = checkInt(activityData.startTime),
                endTime    = checkInt(activityData.endTime),
                closeTime  = checkInt(activityData.closeTime),
            })
        end
    end

    table.sort(self.homeActivityDatas, function(aData, bData)
        local aPriority = 0
        local bPriority = 0
        aPriority = aPriority + (aData.startTime > bData.startTime and 100 or 0)
        bPriority = bPriority + (bData.startTime > aData.startTime and 100 or 0)
        aPriority = aPriority + (aData.endTime < bData.endTime and 10 or 0)
        bPriority = bPriority + (bData.endTime < aData.endTime and 10 or 0)
        aPriority = aPriority + (aData.activityId > bData.activityId and 1 or 0)
        bPriority = bPriority + (bData.activityId > aData.activityId and 1 or 0)
        return aPriority > bPriority
    end)

    Events.Broadcast(Constants.EventNames.HOME_GACHAPON_ACTIVITY_UPDATE)
end

---@return table[]
function GachaponComponent:GetHomeActivityDatas()
    return checkTable(self.homeActivityDatas)
end


---@param consumeMap table[] @ 全部抽卡消耗数据
function GachaponComponent:UpdateConsumeDatas(consumeDatas)
    self.allConsumeDataMap_ = {}
    for _, consumeData in ipairs(checkTable(consumeDatas)) do
        self.allConsumeDataMap_[checkInt(consumeData.poolId)] = consumeData
        if next(checkTable(consumeData.freeData)) ~= nil then
            consumeData.freeData = GachaponFreeDojo.New():Fill(consumeData.freeData)
        end
    end
    self:CheckFreeCountdown()
end

---@return table<integer, table> @ 抽卡消耗数据map { key : 卡池id, value : { poolId:integer, poolType:integer, oneConsume:table, tenConsume:table, isOpenTenRed:integer } }
function GachaponComponent:GetConsumeDataMap()
    return checkTable(self.allConsumeDataMap_)
end


function GachaponComponent:StopFreeCountdown()
    if not isNull(self.freeRefreshTimer_) then
        CfUtils.CDTimerRemove(self.freeRefreshTimer_)
        self.freeRefreshTimer_ = nil
    end
end

function GachaponComponent:CheckFreeCountdown()
    self:StopFreeCountdown()

    local minLeftSeconds = 0
    for _, consumeData in pairs(self:GetConsumeDataMap()) do
        ---@type GachaponFreeDojo
        local callFreeData = consumeData.freeData
        if callFreeData and next(callFreeData) ~= nil and callFreeData.oneLeftSeconds > 0 then
            if minLeftSeconds == 0 then
                minLeftSeconds = checkInt(callFreeData.oneLeftSeconds)
            else
                minLeftSeconds = math.min(minLeftSeconds, checkInt(callFreeData.oneLeftSeconds))
            end
        end
    end
    if minLeftSeconds <= 0 then
        return
    end
    
    self.freeRefreshTimer_ = CfUtils.CDTimerAppend(1, minLeftSeconds, true, true, function(count)
        for _, consumeData in pairs(self:GetConsumeDataMap()) do
            ---@type GachaponFreeDojo
            local callFreeData = consumeData.freeData
            if callFreeData and next(callFreeData) ~= nil then
                if callFreeData.oneLeftSeconds > 0 then
                    callFreeData:UpdateOneLeftSeconds()
                end
            end
        end
        -- update ui
        if Events.HasListener(Constants.EventNames.GACHAPON_FREE_TIMES_COUNTDOWN) then
            Events.Broadcast(Constants.EventNames.GACHAPON_FREE_TIMES_COUNTDOWN)
        end
        if count == 0 then
            -- 更新红点
            GachaponUtils.CheckFreeCallRedPoint()
            self:CheckFreeCountdown()
        end
    end)
end


return GachaponComponent